test('renderInvoiceText displays all elements in correct order', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  let invoice = invoiceResult.value;
  invoice.dueDate = '2024-02-14';
  invoice.voucher = { code: 'SUMMER2024', amount: 5000 };
  invoice.payments = [{ amount: 50000 }];

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Find indices
  const lineIndex = lines.findIndex(l => l.includes('Design work'));
  const discountLineIndex = lines.findIndex(l => l.includes('Discount:'));
  const voucherLineIndex = lines.findIndex(l => l.includes('Voucher:'));
  const totalLineIndex = lines.findIndex(l => l.startsWith('Total:'));
  const dueLineIndex = lines.findIndex(l => l.startsWith('Due:'));
  const paidLineIndex = lines.findIndex(l => l.startsWith('Paid:'));

  // Verify order: line < discount < voucher < total < due < paid
  assert.ok(lineIndex < discountLineIndex);
  assert.ok(discountLineIndex < voucherLineIndex);
  assert.ok(voucherLineIndex < totalLineIndex);
  assert.ok(totalLineIndex < dueLineIndex);
  assert.ok(dueLineIndex < paidLineIndex);
});

