test('renderInvoiceText shows voucher before total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  let invoice = invoiceResult.value;

  // Manually add voucher
  invoice.voucher = { code: 'SUMMER2024', amount: 10000 };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Find voucher and total lines
  const voucherLineIndex = lines.findIndex(l => l.includes('Voucher:'));
  const totalLineIndex = lines.findIndex(l => l.startsWith('Total:'));

  assert.ok(voucherLineIndex >= 0, 'Voucher line should exist');
  assert.ok(totalLineIndex > voucherLineIndex, 'Total should come after voucher');
  assert.ok(text.includes('Voucher: -€100.00'));
});

